sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Display error message when return_date is less than departure_date
   var return_date = g_form.getValue('return_date');
   var departure_date = g_form.getValue('departure_date');

   if (return_date < departure_date) {
	g_form.addErrorMessage('"Return Date" cannot be earlier than "Departure Date"!');
	g_form.setValue('return_date', '');
   }

}
